abstract={This article deals with stationary localized solutions of the (2D) two-dimensional complex Swift-Hohenberg equation (CSHE). Our approach is based on the semi-analytical method of collective coordinate approach. According to the parameters of the equation and a suitable choice of ansatz, the stationary dissipative solitons of the 2D CSHE equation are mapped. This approach allows to describe the influence of the parameters of the equation on the various physical parameters of the pulse and their dynamics. Finally, the major impact of spectral filtering terms on the dynamic of the solitons is demonstrated.},
doi={10.12691/ijp-4-4-2}
publisher={Science and Education Publishing}
